<?php
/** Proof — settings, numbering, tax rates, items, posting rules, sites, agents (spec "Proof", 4–5). */
require __DIR__ . '/lib.php';
$owner = as_member(1);
echo "1. settings_save\n";
[$c, $d] = screen($owner, '/settings/general');
ok($c === 200 && $d['settings']['base_currency'] === 'USD' && $d['settings']['ar_account_id'] === account_id('1200') && $d['settings']['reminder_days'] === [7, 21, 45], 'the screen answers the seeded settings');
$fixedBefore = $d['currency_fixed'];
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/general.php', ['business_name' => 'SMOKE Books Ltd', 'invoice_terms_days' => '14', 'reminder_days' => '10, 30', 'ai_statement_poll' => 'no']);
ok($c === 200 && ($b['changed'] ?? []) === ['business_name', 'invoice_terms_days', 'reminder_days', 'ai_statement_poll'], 'four keys changed');
$log = activity('settings.save', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['before'], true) == ['business_name' => null, 'invoice_terms_days' => 30, 'reminder_days' => [7, 21, 45], 'ai_statement_poll' => true]
   && json_decode((string) $log[0]['after'], true) == ['business_name' => 'SMOKE Books Ltd', 'invoice_terms_days' => 14, 'reminder_days' => [10, 30], 'ai_statement_poll' => false], 'settings.save logs before/after of the changed keys only');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/general.php', ['invoice_terms_days' => '14']);
ok($c === 200 && ($b['did'] ?? '') === 'Nothing changed' && activity('settings.save', $since) === [], '"Nothing changed" logs nothing');
[$c, $b] = act($owner, '/settings/general.php', ['ar_account' => account_id('6100')]);
ok($c === 422 && (fields($b)['ar_account'] ?? '') === 'Accounts receivable is an asset account.', 'the AR control narrowed to assets: 422 "Accounts receivable is an asset account."');
[$c, $b] = act($owner, '/settings/general.php', ['sales_tax_account' => account_id('1010')]);
ok($c === 422 && str_contains(fields($b)['sales_tax_account'] ?? '', 'liability'), 'sales tax narrowed to liabilities');
[$c, $b] = act($owner, '/settings/general.php', ['bad_debt_account' => account_id('6100')]);
ok($c === 200 && (int) one('SELECT bad_debt_account_id FROM gl_settings') === account_id('6100'), 'bad debt to another expense account: 200');
[$c, $b] = act($owner, '/settings/general.php', ['base_currency' => 'eur']);
if ($fixedBefore) {
    ok($c === 422 && (fields($b)['base_currency'] ?? '') === 'The base currency is fixed once the books hold a document.', 'the base currency with documents in the books: 422 "fixed"');
} else {
    ok($c === 200 && (string) one('SELECT base_currency FROM gl_settings') === 'EUR', 'the base currency before any document: changed (upper-cased)');
    act($owner, '/settings/general.php', ['base_currency' => 'USD']);
    q("INSERT INTO customers (name) VALUES ('SMOKE Cust')");
    q("INSERT INTO invoices (customer_id, invoice_date, due_date, currency) VALUES ((SELECT id FROM customers WHERE name = 'SMOKE Cust'), '2026-02-01', '2026-03-01', 'USD')");
    [$c, $b] = act($owner, '/settings/general.php', ['base_currency' => 'EUR']);
    ok($c === 422 && (fields($b)['base_currency'] ?? '') === 'The base currency is fixed once the books hold a document.', 'after an invoice exists (SQL): 422 "The base currency is fixed once the books hold a document."');
}
ok(str_contains(page($owner, '/settings/general')['body'], 'readonly'), 'and the form shows it read-only');
[$c, $b] = act($owner, '/settings/general.php', ['reminder_days' => '7, 400']);
ok($c === 422 && isset(fields($b)['reminder_days']), 'a reminder day over 365: 422');
[$c, $b] = act($owner, '/settings/general.php', ['timezone' => 'Mars/Olympus']);
ok($c === 422 && isset(fields($b)['timezone']), 'a bad time zone: 422');
[$c, $b] = act($owner, '/settings/general.php', ['morning_note_member' => 40]);
ok($c === 200 && (int) one('SELECT morning_note_member_id FROM gl_settings') === 40, 'the morning note to the Bookkeeper agent: 200');
$body = page($owner, '/settings/general')['body'];
$arSel = substr($body, strpos($body, 'id="settings-form-field-ar_account"'), strpos($body, 'id="settings-form-field-ap_account"') - strpos($body, 'id="settings-form-field-ar_account"'));
ok(preg_match_all('/id="settings-form-field-(ar_account|ap_account|undeposited_funds_account|sales_tax_account|ai_usage_account|retained_earnings_account|bad_debt_account)"/', $body) === 7 && !str_contains($arSel, '>6100 ') && str_contains($arSel, '>1200 '), 'the form: seven control selects; the AR select offers 1200 and no expense account');
echo "2. numbering_save\n";
[$c, $d] = screen($owner, '/settings/numbering');
$inv = array_values(array_filter($d['numbering'], fn ($r) => $r['kind'] === 'invoice'))[0];
ok($c === 200 && $inv['prefix'] === 'INV-' && $inv['next_value'] === 1 && $inv['preview'] === 'INV-00001', 'the invoice sequence: INV-, next 1, preview INV-00001');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/numbering.php', ['kind' => 'invoice', 'prefix' => 'sal-', 'next_value' => '42']);
ok($c === 200 && ($b['preview'] ?? '') === 'SAL-00042' && count(activity('numbering.save', $since)) === 1, 'prefix SAL- and next 42: preview SAL-00042, numbering.save logged');
[$c, $b] = act($owner, '/settings/numbering.php', ['kind' => 'invoice', 'next_value' => '10']);
ok($c === 422 && str_contains(msg($b), 'The next number cannot go below the current'), 'lowering the next value: 422 "The next number cannot go below the current"');
ok((string) one("SELECT next_document_number('invoice')") === 'SAL-00042' && (string) one("SELECT next_document_number('invoice')") === 'SAL-00043', 'next_document_number() hands out SAL-00042 then SAL-00043 (SQL)');
[$c, $b] = act($owner, '/settings/numbering.php', ['kind' => 'other', 'prefix' => 'X']);
ok($c === 422, 'an unknown kind: 422');
[$c, $b] = act($owner, '/settings/numbering.php', ['kind' => 'bill', 'prefix' => 'toolongprefix']);
ok($c === 422 && isset(fields($b)['prefix']), 'a bad prefix: 422');
$body = page($owner, '/settings/numbering')['body'];
ok(str_contains($body, 'id="numbering-row-invoice-preview">SAL-00044<') , 'the table previews the next number (SAL-00044 after two were taken)');
echo "3. Tax rates\n";
$def = (int) one('SELECT id FROM tax_rates WHERE is_default');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE State tax', 'rate' => '8.25']);
$t1 = (int) $b['record_id'];
ok($c === 200 && $t1 > 0 && str_ends_with((string) $b['location'], '#tax-rate-row-' . $t1), 'tax_rate_save: a rate added, location the row');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE City tax', 'rate' => '1.5', 'is_default' => 'yes']);
$t2 = (int) $b['record_id'];
ok($c === 200 && (int) one('SELECT count(*) FROM tax_rates WHERE is_default') === 1 && (int) one('SELECT id FROM tax_rates WHERE is_default') === $t2, 'a new default un-defaults the other: one default, the new one');
[$c, $b] = act($owner, '/settings/tax-rates/archive.php', ['tax_rate' => $t2]);
ok($c === 422 && msg($b) === 'Make another rate the default first.', 'archiving the default: 422 "Make another rate the default first."');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['tax_rate' => $t2, 'is_default' => 'no']);
ok($c === 422 && msg($b) === 'Make another rate the default first.', 'un-defaulting it directly: 422 too');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['tax_rate' => $def, 'is_default' => 'yes']);
ok($c === 200 && (int) one('SELECT id FROM tax_rates WHERE is_default') === $def, 'No tax is the default again');
[$c, $b] = act($owner, '/settings/tax-rates/archive.php', ['tax_rate' => $t2]);
ok($c === 200 && one('SELECT archived_at FROM tax_rates WHERE id = :i', ['i' => $t2]) !== null, 'and the city tax archives');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE State tax', 'rate' => '9']);
ok($c === 422 && str_contains(msg($b), 'already exists'), 'a duplicate name: 422');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE Too much', 'rate' => '100']);
ok($c === 422 && isset(fields($b)['rate']), 'a rate of 100: 422');
echo "4. Items\n";
[$c, $b] = act($owner, '/settings/items/save.php', ['name' => 'SMOKE Consulting hour', 'code' => 'CONS-H', 'kind' => 'service', 'unit' => 'hour', 'unit_price' => '1,250.00', 'income_account' => account_id('4000'), 'tax_rate' => $t1]);
$it = (int) $b['record_id'];
ok($c === 200 && $it > 0 && (string) one('SELECT unit_price FROM items WHERE id = :i', ['i' => $it]) === '1250.00', 'item_save: added, the price parsed from "1,250.00"');
[$c, $b] = act($owner, '/settings/items/save.php', ['name' => 'SMOKE Wrong income', 'income_account' => account_id('6100')]);
ok($c === 422 && isset(fields($b)['income_account']), 'an expense account as income: 422 (narrowed)');
[$c, $b] = act($owner, '/settings/items/save.php', ['name' => 'SMOKE Wrong expense', 'expense_account' => account_id('4000')]);
ok($c === 422 && isset(fields($b)['expense_account']), 'an income account as expense: 422');
[$c, $b] = act($owner, '/settings/items/save.php', ['name' => 'SMOKE Dupe code', 'code' => 'cons-h']);
ok($c === 422 && str_contains(msg($b), 'already used by SMOKE Consulting hour'), 'a code in use (case-blind): 422 naming the owner');
[$c, $b] = act($owner, '/settings/items/save.php', ['item' => $it, 'unit_price' => '1300']);
ok($c === 200 && (string) one('SELECT name FROM items WHERE id = :i', ['i' => $it]) === 'SMOKE Consulting hour' && (string) one('SELECT unit_price FROM items WHERE id = :i', ['i' => $it]) === '1300.00', 'item_update with one field keeps the rest');
[$c, $d] = screen($owner, '/settings/items/?q=cons');
ok(count($d['items']) === 1 && $d['items'][0]['income_account']['code'] === '4000' && $d['items'][0]['tax_rate']['name'] === 'SMOKE State tax', 'the list filters by code and names the accounts and the rate');
[$c, $b] = act($owner, '/settings/items/archive.php', ['item' => $it]);
ok($c === 200 && count(screen($owner, '/settings/items/')[1]['items']) === 0 && count(screen($owner, '/settings/items/?include_archived=1')[1]['items']) === 1, 'archived: off the list unless include_archived');
act($owner, '/settings/items/archive.php', ['item' => $it, 'archived' => 'no']);
echo "5. Posting rules\n";
[$c, $d] = screen($owner, '/settings/posting-rules/');
$inv = array_values(array_filter($d['posting_rules'], fn ($r) => $r['source'] === 'invoice' && $r['match_key'] === null))[0];
ok($c === 200 && $inv['debit_account']['code'] === '1200' && str_starts_with((string) $inv['credit_account']['code'], '4') && $inv['source_label'] === 'Invoice issued', 'the invoice rule: 1200 / ' . $inv['credit_account']['code'] . ', in words');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/posting-rules/save.php', ['rule' => $inv['posting_rule_id'], 'tax_account' => account_id('2100'), 'note' => 'SMOKE tax to 2100']);
$pl = activity('posting_rule.save', $since);
$pa = $pl === [] ? [] : json_decode((string) $pl[0]['after'], true);
ok($c === 200 && count($pl) === 1 && ($pa['note'] ?? '') === 'SMOKE tax to 2100' && !array_key_exists('source', $pa) && !array_key_exists('debit_account_id', $pa), 'the rule saved by id; posting_rule.save logs only the changed fields (' . implode(', ', array_keys($pa)) . ')');
ok((int) one("SELECT tax_account_id FROM gl_posting_rule('invoice')") === account_id('2100'), 'gl_posting_rule(invoice) reads it back');
[$c, $b] = act($owner, '/settings/posting-rules/save.php', ['rule' => 'bill', 'match_key' => 'hosting', 'debit_account' => account_id('6100'), 'credit_account' => account_id('2000')]);
$keyed = (int) $b['record_id'];
ok($c === 200 && $keyed > 0 && (int) one("SELECT id FROM gl_posting_rule('bill', 'hosting')") === $keyed && (int) one("SELECT id FROM gl_posting_rule('bill', 'other')") !== $keyed, 'a keyed rule by source + match_key: gl_posting_rule(bill, hosting) finds it; another key falls to the default');
[$c, $b] = act($owner, '/settings/posting-rules/save.php', ['rule' => 'bill', 'match_key' => 'hosting', 'active' => 'no']);
ok($c === 200 && (int) $b['record_id'] === $keyed && one("SELECT id FROM gl_posting_rule('bill', 'hosting')") != $keyed, 'naming the same source + key again updates it (off): the function falls to the default');
[$c, $b] = act($owner, '/settings/posting-rules/save.php', ['rule' => 'magic']);
ok($c === 422 && str_contains(msg($b), 'No posting source is called magic'), 'an unknown source: 422');
echo "6. Sites\n";
[$c, $b] = act($owner, '/settings/sites/save.php', ['name' => 'SMOKE Main Street', 'kernel_location' => '17', 'address' => '1 Main St']);
$site = (int) $b['record_id'];
ok($c === 200 && $site > 0 && (int) one('SELECT kernel_location_id FROM sites WHERE id = :s', ['s' => $site]) === 17, 'site_save: added with the OS location pinned');
$sl = activity('site.save', 0);
ok($sl !== [] && (int) end($sl)['site_id'] === $site, 'site.save carries site_id');
[$c, $b] = act($owner, '/settings/sites/save.php', ['name' => 'smoke main street']);
ok($c === 422 && str_contains(msg($b), 'already exists'), 'a duplicate name: 422');
[$c, $b] = act($owner, '/settings/sites/archive.php', ['site' => $site]);
ok($c === 200 && count(screen($owner, '/settings/sites/')[1]['sites']) === 0, 'archived: off the list');
act($owner, '/settings/sites/archive.php', ['site' => $site, 'archived' => 'no']);
$body = page($owner, '/accounts/' . account_id('6100'))['body'];
ok(str_contains($body, '<option value="' . $site . '"'), 'a live site is offered on the account activity filter');
echo "7. Agents\n";
[$c, $d] = screen($owner, '/settings/agents');
$ag = array_values(array_filter($d['agents'], fn ($a) => $a['member_id'] === 40))[0] ?? null;
ok($c === 200 && $ag !== null && $ag['roles'] === ['bookkeeper', 'user'] && $ag['last_dispatch'] === null, 'the Bookkeeper agent is listed with its roles, never dispatched');
q("INSERT INTO agent_dispatches (record_type, record_id, agent_member_id, kind, via, acting_member_id, status) VALUES ('bill', 1, 40, 'ask', 'chat', 1, 'answered')");
[$c, $d] = screen($owner, '/settings/agents');
$ag = array_values(array_filter($d['agents'], fn ($a) => $a['member_id'] === 40))[0];
ok($ag['last_dispatch']['kind'] === 'ask' && str_contains(page($owner, '/settings/agents')['body'], 'id="agent-card-40"'), 'a dispatch shows on the card');
finish();
